'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var logpdf = require( './../lib' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof logpdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', function test( t ) {
	var y = logpdf( NaN, 1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = logpdf( 0.0, NaN, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = logpdf( 0.0, 1.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a nonpositive `mu`, the function always returns `NaN`', function test( t ) {
	var y;

	y = logpdf( 2.0, 0.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logpdf( 2.0, -1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logpdf( 2.0, NINF, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `+infinity` for `x` and a valid `mu` and `lambda`, the function returns `-infinity`', function test( t ) {
	var y = logpdf( PINF, 1.0, 0.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	y = logpdf( PINF, 1.0, 1.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	t.end();
});

tape( 'if provided `-infinity` for `x` and a valid `mu` and `lambda`, the function returns `-infinity`', function test( t ) {
	var y = logpdf( NINF, 1.0, 0.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	y = logpdf( NINF, 1.0, 1.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	t.end();
});

tape( 'if provided a negative `lambda`, the function always returns `NaN`', function test( t ) {
	var y;

	y = logpdf( 2.0, 0.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logpdf( 0.0, 0.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logpdf( 2.0, 0.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logpdf( 2.0, PINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logpdf( 2.0, NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logpdf( 2.0, NaN, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `lambda` equals `0`, the function evaluates a degenerate distribution centered at `mu`', function test( t ) {
	var y;

	y = logpdf( 2.0, 2.0, 0.0 );
	t.strictEqual( y, PINF, 'returns +infinity for x equal to mu' );

	y = logpdf( 3.0, 2.0, 0.0 );
	t.strictEqual( y, NINF, 'returns -infinity for x greater than mu' );

	y = logpdf( 1.0, 2.0, 0.0 );
	t.strictEqual( y, NINF, 'returns -infinity for x smaller than mu' );

	t.end();
});

tape( 'the function evaluates the logpdf for `x` given parameters `mu` and `lambda`', function test( t ) {
	var expected;
	var lambda;
	var mu;
	var i;
	var x;
	var y;

	expected = data.expected;
	x = data.x;
	mu = data.mu;
	lambda = data.lambda;
	for ( i = 0; i < x.length; i++ ) {
		y = logpdf( x[i], mu[i], lambda[i] );
		if ( y === expected[i] ) {
			t.strictEqual( y, expected[i], 'x: '+x[i]+', mu: '+mu[i]+', lambda: '+lambda[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[ i ], 2 ), 'within tolerance. x: '+x[ i ]+'. mu: '+mu[i]+'. lambda: '+lambda[i]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});
